module digit_rearrange(input clk, input rst_n, input start, input [31:0] digit_vector, input [2:0] num_digits, output reg [39:0] result, output reg [3:0] result_length, output reg done, output reg valid); localparam IDLE = 3'b000; localparam COUNT_DIGITS = 3'b001; localparam REMOVE_SPECIAL = 3'b010; localparam COMPUTE_PREFIX = 3'b011; localparam FIND_PERMUTATION = 3'b100; localparam CONSTRUCT_RESULT = 3'b101; localparam DONE = 3'b110; reg [2:0] state, next_state; reg [2:0] digit_idx; reg [3:0] counts [10]; reg [3:0] prefix_digits [4]; reg [2:0] prefix_len; reg removed_1, removed_6, removed_8, removed_9; reg [2:0] current_mod; reg [15:0] permutation; reg [39:0] result_reg; reg [3:0] result_length_reg; reg valid_reg; reg done_reg; reg [7:0] delay_counter; reg start_triggered; always @(posedge clk or negedge rst_n) begin if (!rst_n) begin state <= IDLE; digit_idx <= 3'b000; counts <= {10{4'b0000}}; prefix_digits <= {4{4'b0000}}; prefix_len <= 3'b000; removed_1 <=0; removed_6<=0; removed_8<=0; removed_9<=0; current_mod <=3'b000; permutation <=16'b0000; result_reg <=40'b0; result_length_reg <=4'b0000; valid_reg <=0; done_reg <=0; delay_counter <=8'b0; start_triggered <=0; end else begin if (state == IDLE) begin if (start) begin start_triggered <=1; next_state <= COUNT_DIGITS; digit_idx <=3'b000; counts <= {10{4'b0000}}; end next_state <= IDLE; end else if (state == COUNT_DIGITS) begin if (digit_idx < num_digits) begin digit_idx <= digit_idx +1; next_state <= COUNT_DIGITS; end else begin next_state <= REMOVE_SPECIAL; end end else if (state == REMOVE_SPECIAL) begin if (counts[1]<1 || counts[6]<1 || counts[8]<1 || counts[9]<1) begin valid_reg <=0; end else begin valid_reg <=1; end next_state <= COMPUTE_PREFIX; end else if (state == COMPUTE_PREFIX) begin next_state <= FIND_PERMUTATION; end else if (state == FIND_PERMUTATION) begin next_state <= CONSTRUCT_RESULT; end else if (state == CONSTRUCT_RESULT) begin next_state <= DONE; end else if (state == DONE) begin if (delay_counter ==0) begin done_reg <= valid_reg; end else begin delay_counter <= delay_counter -1; end next_state <= DONE; end state <= next_state; if (start_triggered && state == DONE) begin if (delay_counter ==0) begin result <= result_reg; result_length <= result_length_reg; valid <= valid_reg; done <= done_reg; end else begin delay_counter <= delay_counter -1; end end end endmodule